-- ════════════════════════════════════════════════════════════════════
-- MotoGo24 — SEED doporučených tras — NIZOZEMSKO (2. dávka, 10 tras)
-- NEAPLIKOVÁNO na živou DB — přehled a spuštění je na adminovi.
-- Trasy: is_active=false (Skryto) + status='approved' → ve Velíně zkontroluj a Publikuj.
-- Idempotence: každá trasa se před vložením smaže dle (name, branch_id).
-- ════════════════════════════════════════════════════════════════════
alter table public.routes add column if not exists countries text[] not null default '{}'::text[];

do $$
declare
  v_branch uuid;
  v_route  uuid;
begin
  -- Domovská pobočka = nejbližší k Mezné (49.3464, 15.2119); fallback první.
  select id into v_branch from public.branches
    order by (power(coalesce(gps_lat,0)-49.3464,2) + power(coalesce(gps_lng,0)-15.2119,2)) asc
    limit 1;
  if v_branch is null then
    raise exception 'Nenalezena žádná pobočka v public.branches — nelze nasadit trasy.';
  end if;

  -- Nizozemsko – Zeeland a Delta Works
  delete from public.routes where name = 'Nizozemsko – Zeeland a Delta Works' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Nizozemsko – Zeeland a Delta Works', 'Okruh po ostrovech Zeelandu, kde se jezdí doslova po moři — silnice vedou po hrázích a přehradních tělesech největšího protipovodňového díla světa. Vrcholem je přejezd bariéry Oosterscheldekering, devět kilometrů betonových pilířů mezi Severním mořem a deltou. Cestou vás čekají pohádkové přístavní městečko Veere, hanzovní Zierikzee i maják ve Westkapelle na nejzápadnějším cípu Walcherenu. Silnice jsou perfektní, provoz mimo sezónu minimální, zatáčky nahrazuje neskutečný pocit jízdy mezi dvěma vodními hladinami. Nejlepší je jaro a začátek podzimu; celoročně počítejte se silným bočním větrem na hrázích — v Zeelandu fouká prakticky pořád.', 'loop', 120, 200, 'easy',
     '[{"lat": 51.4988, "lng": 3.6136, "label": "Start: Middelburg"}, {"lat": 51.5470, "lng": 3.6670, "label": "Veere"}, {"lat": 51.6218, "lng": 3.6870, "label": "Oosterscheldekering"}, {"lat": 51.6500, "lng": 3.9167, "label": "Zierikzee"}, {"lat": 51.5280, "lng": 3.4430, "label": "Westkapelle"}, {"lat": 51.5620, "lng": 3.4970, "label": "Domburg"}, {"lat": 51.4988, "lng": 3.6136, "label": "Cíl: Middelburg"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=51.4988,3.6136&destination=51.4988,3.6136&travelmode=driving&waypoints=51.5470,3.6670%7C51.6218,3.6870%7C51.6500,3.9167%7C51.5280,3.4430%7C51.5620,3.4970', 'https://commons.wikimedia.org/wiki/Special:FilePath/Oosterscheldekering-pohled.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Grote%20Kerk%20Veere.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Campveerse%20Toren.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Oosterscheldekering-pohled.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Zierikzee.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Vuurtoren%20Westkapelle.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Domburg.jpg"}'::text[], '{"Veere – přístav a Grote Kerk","Restaurace: De Campveerse Toren (Veere)","Oosterscheldekering","Zierikzee","Westkapelle – maják","Domburg"}'::text[], '{"NL"}'::text[], false, 4510, 'approved');

  -- Nizozemsko – Friesland a města Elfstedentocht
  delete from public.routes where name = 'Nizozemsko – Friesland a města Elfstedentocht' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Nizozemsko – Friesland a města Elfstedentocht', 'Okruh po stopách legendárního bruslařského závodu Elfstedentocht, který spojuje historická fríská města. Na motorce si projedete jeho jihozápadní polovinu: Leeuwarden se šikmou věží Oldehove, Sneek s ikonickou vodní bránou a řadu miniaturních přístavních měst na břehu IJsselmeeru. Silnice se vinou mezi kanály, pastvinami a zvedacími mosty — typická fríská krajina, kde je víc vody než pevniny. Provoz je řídký, tempo poklidné, zážitek maximální. Nejhezčí je od května do září; na hrázích IJsselmeeru počítejte s větrem a v ranních hodinách s mlhou nad kanály.', 'loop', 130, 210, 'easy',
     '[{"lat": 53.2028, "lng": 5.7889, "label": "Start: Leeuwarden"}, {"lat": 53.0330, "lng": 5.6580, "label": "Sneek"}, {"lat": 52.8830, "lng": 5.3610, "label": "Stavoren"}, {"lat": 52.9420, "lng": 5.4030, "label": "Hindeloopen"}, {"lat": 52.9790, "lng": 5.4470, "label": "Workum"}, {"lat": 53.0630, "lng": 5.5280, "label": "Bolsward"}, {"lat": 53.2028, "lng": 5.7889, "label": "Cíl: Leeuwarden"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=53.2028,5.7889&destination=53.2028,5.7889&travelmode=driving&waypoints=53.0330,5.6580%7C52.8830,5.3610%7C52.9420,5.4030%7C52.9790,5.4470%7C53.0630,5.5280', 'https://commons.wikimedia.org/wiki/Special:FilePath/Waterpoort%20Sneek.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Oldehove%20Leeuwarden.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Waterpoort%20Sneek.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Stavoren.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Hindeloopen.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Workum.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Stadhuis%20Bolsward.jpg"}'::text[], '{"Leeuwarden – Oldehove","Sneek – Waterpoort","Stavoren","Hindeloopen","Workum","Bolsward – radnice"}'::text[], '{"NL"}'::text[], false, 4520, 'approved');

  -- Nizozemsko – Veluwezoom, Posbank a Arnhem
  delete from public.routes where name = 'Nizozemsko – Veluwezoom, Posbank a Arnhem' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Nizozemsko – Veluwezoom, Posbank a Arnhem', 'Nejzatáčkovitější kousek Nizozemska: národní park Veluwezoom s vyhlídkou Posbank je nedělní mekkou holandských motorkářů — vlnitá silnička stoupá vřesovišti do „závratných" 90 metrů nad mořem. Okruh přidává nejmenší město země Bronkhorst, barokní královský palác Het Loo a katedrálu vysílací techniky Radio Kootwijk uprostřed písečných dun. Závěr patří válečné historii: Oosterbeek a arnhemský most, o který se bojovalo v operaci Market Garden. Lesní úseky svádějí k tempu, ale pozor na zvěř, cyklisty a víkendové kontroly rychlosti. Nejkrásněji je tu v srpnu a září, kdy kvete vřes.', 'loop', 140, 220, 'medium',
     '[{"lat": 51.9770, "lng": 5.9110, "label": "Start: Arnhem"}, {"lat": 52.0330, "lng": 6.0210, "label": "Posbank"}, {"lat": 52.0700, "lng": 6.1930, "label": "Bronkhorst"}, {"lat": 52.2333, "lng": 5.9450, "label": "Paleis Het Loo"}, {"lat": 52.1730, "lng": 5.8140, "label": "Radio Kootwijk"}, {"lat": 51.9880, "lng": 5.8320, "label": "Oosterbeek"}, {"lat": 51.9770, "lng": 5.9110, "label": "Cíl: Arnhem"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=51.9770,5.9110&destination=51.9770,5.9110&travelmode=driving&waypoints=52.0330,6.0210%7C52.0700,6.1930%7C52.2333,5.9450%7C52.1730,5.8140%7C51.9880,5.8320', 'https://commons.wikimedia.org/wiki/Special:FilePath/Posbank.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/John%20Frostbrug.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Posbank.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Bronkhorst.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Paleis%20Het%20Loo.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Radio%20Kootwijk.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Airborne%20Museum%20Hartenstein.jpg"}'::text[], '{"Arnhem – John Frostbrug","Posbank","Bronkhorst","Paleis Het Loo","Radio Kootwijk","Airborne Museum Hartenstein (Oosterbeek)"}'::text[], '{"NL"}'::text[], false, 4530, 'approved');

  -- Nizozemsko – kopce jižního Limburgu
  delete from public.routes where name = 'Nizozemsko – kopce jižního Limburgu' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Nizozemsko – kopce jižního Limburgu', 'Jediný kout Nizozemska, kde se opravdu jezdí do kopce: Heuvelland mezi Maastrichtem a Cáchami nabízí úzké silničky mezi hrázděnými statky, sady a vinicemi, stoupání s výhledy do tří zemí a legendární cyklistický Cauberg. Na Vaalserbergu se u Drielandenpuntu potkávají hranice Nizozemska, Belgie a Německa — zároveň nejvyšší bod evropské části země. Cestou zpět vás čeká hradní zřícenina nad Valkenburgem a náměstí Vrijthof v Maastrichtu. Serpentiny jsou krátké, ale šťavnaté; pozor na hejna cyklistů, o víkendech jich tu jsou tisíce. Ideální od jara do podzimu, silnice jsou úzké a po dešti kluzké od bláta z polí.', 'loop', 95, 180, 'medium',
     '[{"lat": 50.8490, "lng": 5.6880, "label": "Start: Maastricht"}, {"lat": 50.7540, "lng": 6.0210, "label": "Drielandenpunt (Vaals)"}, {"lat": 50.7710, "lng": 5.9130, "label": "Epen"}, {"lat": 50.8140, "lng": 5.8900, "label": "Gulpen"}, {"lat": 50.8620, "lng": 5.8320, "label": "Valkenburg"}, {"lat": 50.8490, "lng": 5.6880, "label": "Cíl: Maastricht"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=50.8490,5.6880&destination=50.8490,5.6880&travelmode=driving&waypoints=50.7540,6.0210%7C50.7710,5.9130%7C50.8140,5.8900%7C50.8620,5.8320', 'https://commons.wikimedia.org/wiki/Special:FilePath/Vrijthof%20Maastricht.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Drielandenpunt.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Epen.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Gulpen.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Kasteel%20Valkenburg.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Cauberg.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Vrijthof%20Maastricht.jpg"}'::text[], '{"Drielandenpunt (Vaals)","Epen – hrázděný Heuvelland","Restaurace: Gulpener Brouwlokaal (Gulpen)","Kasteel Valkenburg","Cauberg","Maastricht – Vrijthof"}'::text[], '{"NL"}'::text[], false, 4540, 'approved');

  -- Nizozemsko – pobřeží Waddenzee
  delete from public.routes where name = 'Nizozemsko – pobřeží Waddenzee' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Nizozemsko – pobřeží Waddenzee', 'Jízda podél Waddenského moře, jediné nizozemské přírodní památky UNESCO: po vnitřní straně mořských hrází vedou prázdné silničky, za nimi se při odlivu obnažují kilometry bahnitých plání plných ptactva. Trasa spojuje přístavní Harlingen, nejstarší funkční planetárium světa ve Franekeru a poutní Dokkum s národním parkem Lauwersmeer. Závěr patří rybářskému Zoutkampu a Pieterburenu se známou tulení záchrannou stanicí. Rovinatá, meditativní jízda s nekonečným horizontem — tohle je Nizozemsko bez turistů. Kdykoli od jara do podzimu; na hrázích fouká a v ptačí sezóně platí místy omezení rychlosti.', 'poi', 115, 185, 'easy',
     '[{"lat": 53.1740, "lng": 5.4210, "label": "Start: Harlingen"}, {"lat": 53.1870, "lng": 5.5420, "label": "Franeker"}, {"lat": 53.3260, "lng": 5.9990, "label": "Dokkum"}, {"lat": 53.4000, "lng": 6.2200, "label": "Lauwersoog"}, {"lat": 53.3370, "lng": 6.2940, "label": "Zoutkamp"}, {"lat": 53.3960, "lng": 6.4400, "label": "Cíl: Pieterburen"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=53.1740,5.4210&destination=53.3960,6.4400&travelmode=driving&waypoints=53.1870,5.5420%7C53.3260,5.9990%7C53.4000,6.2200%7C53.3370,6.2940', 'https://commons.wikimedia.org/wiki/Special:FilePath/Harlingen%20haven.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Harlingen%20haven.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Eise%20Eisinga%20Planetarium.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Dokkum.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Lauwersmeer.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Zoutkamp.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Pieterburen.jpg"}'::text[], '{"Harlingen","Franeker – planetárium Eise Eisingy","Dokkum","Nationaal Park Lauwersmeer","Zoutkamp","Pieterburen"}'::text[], '{"NL"}'::text[], false, 4550, 'approved');

  -- Nizozemsko – ostrov Texel
  delete from public.routes where name = 'Nizozemsko – ostrov Texel' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Nizozemsko – ostrov Texel', 'Největší z Waddenských ostrovů je stvořený pro jednodenní ostrovní výpravu: z Den Helderu vás dvacetiminutový trajekt TESO přepraví i s motorkou a pak už následují prázdné silničky mezi ovčími pastvinami, dunami a majáky. Trasa vede přes hlavní městečko Den Burg a rybářský Oudeschild podél východního pobřeží až k červenému majáku Eierland na severním cípu. Národní park Duinen van Texel s centrem Ecomare ukazuje tuleně i ptačí kolonie. Ostrovní tempo je pomalé a předjíždění ovcí patří ke koloritu — spěch nechte na pevnině. Nejlépe od dubna do října; trajekty jezdí celoročně každou hodinu, v létě častěji.', 'poi', 60, 150, 'easy',
     '[{"lat": 52.9600, "lng": 4.7910, "label": "Start: Den Helder (trajekt)"}, {"lat": 53.0540, "lng": 4.7970, "label": "Den Burg"}, {"lat": 53.0390, "lng": 4.8500, "label": "Oudeschild"}, {"lat": 53.0930, "lng": 4.7560, "label": "Ecomare"}, {"lat": 53.1790, "lng": 4.8550, "label": "Cíl: maják Eierland"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=52.9600,4.7910&destination=53.1790,4.8550&travelmode=driving&waypoints=53.0540,4.7970%7C53.0390,4.8500%7C53.0930,4.7560', 'https://commons.wikimedia.org/wiki/Special:FilePath/Vuurtoren%20Eierland.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Den%20Burg.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Oudeschild.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Ecomare.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Duinen%20van%20Texel.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Vuurtoren%20Eierland.jpg"}'::text[], '{"Restaurace: De Twaalf Balcken (Den Burg)","Oudeschild – muzeum Kaap Skil","Ecomare","Nationaal Park Duinen van Texel","Maják Eierland"}'::text[], '{"NL"}'::text[], false, 4560, 'approved');

  -- Nizozemsko – tulipánová pole a Zandvoort
  delete from public.routes where name = 'Nizozemsko – tulipánová pole a Zandvoort' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Nizozemsko – tulipánová pole a Zandvoort', 'Krátký okruh s největší barevnou koncentrací na světě: od poloviny dubna do začátku května kvetou v Bollenstreeku mezi Haarlemem a Leidenem miliony tulipánů a silničky mezi lány připomínají jízdu obřím pruhovaným kobercem. K tomu legendární okruh Zandvoort v dunách, kde se jezdí Velká cena Nizozemska F1, přímořský Noordwijk s majákem a květinový park Keukenhof. Návrat vede přes Haarlem s grandiózním náměstím u katedrály. Mimo tulipánovou sezónu je trasa příjemnou přímořskou vyjížďkou dunami. V dubnu počítejte s hustým provozem kolem Keukenhofu — vyjeďte brzy ráno, kdy jsou pole nejkrásnější a silnice prázdné.', 'loop', 85, 160, 'easy',
     '[{"lat": 52.3810, "lng": 4.6360, "label": "Start: Haarlem"}, {"lat": 52.3888, "lng": 4.5409, "label": "Zandvoort"}, {"lat": 52.2420, "lng": 4.4320, "label": "Noordwijk"}, {"lat": 52.2700, "lng": 4.5460, "label": "Keukenhof"}, {"lat": 52.2580, "lng": 4.5570, "label": "Lisse"}, {"lat": 52.3810, "lng": 4.6360, "label": "Cíl: Haarlem"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=52.3810,4.6360&destination=52.3810,4.6360&travelmode=driving&waypoints=52.3888,4.5409%7C52.2420,4.4320%7C52.2700,4.5460%7C52.2580,4.5570', 'https://commons.wikimedia.org/wiki/Special:FilePath/Keukenhof.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Circuit%20Zandvoort.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Vuurtoren%20Noordwijk.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Keukenhof.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Bollenvelden%20bij%20Lisse.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Grote%20Markt%20Haarlem.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Jopenkerk%20Haarlem.jpg"}'::text[], '{"Circuit Zandvoort","Noordwijk – maják","Keukenhof","Tulipánová pole u Lisse","Haarlem – Grote Markt","Restaurace: Jopenkerk (Haarlem)"}'::text[], '{"NL"}'::text[], false, 4570, 'approved');

  -- Nizozemsko – Waterland a sýrový Edam
  delete from public.routes where name = 'Nizozemsko – Waterland a sýrový Edam' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Nizozemsko – Waterland a sýrový Edam', 'Pohlednicové Holandsko na dosah Amsterdamu, ale bez jeho davů: okruh krajinou Waterlandu spojuje bývalý ostrov Marken s dřevěnými domky na kůlech, rybářský Volendam, sýrový Edam a trojici mlýnů u Schermerhornu. Jezdí se po úzkých silničkách na hrázích mezi kanály, kde je člověk pořád pár desítek centimetrů nad vodou. Slavný maják Paard van Marken na východním cípu ostrova je nejfotogeničtější stavba Markermeeru. Trasa je krátká a pohodová, ideální na půlden s dlouhými zastávkami na sýr a uzené úhoře. Celoročně sjízdná; na hrázových silničkách pozor na protijedoucí cyklisty a silný vítr od jezera.', 'loop', 85, 160, 'easy',
     '[{"lat": 52.4570, "lng": 5.0380, "label": "Start: Monnickendam"}, {"lat": 52.4580, "lng": 5.1090, "label": "Marken"}, {"lat": 52.4950, "lng": 5.0700, "label": "Volendam"}, {"lat": 52.5130, "lng": 5.0480, "label": "Edam"}, {"lat": 52.6060, "lng": 4.8890, "label": "Schermerhorn"}, {"lat": 52.4350, "lng": 5.0000, "label": "Broek in Waterland"}, {"lat": 52.4570, "lng": 5.0380, "label": "Cíl: Monnickendam"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=52.4570,5.0380&destination=52.4570,5.0380&travelmode=driving&waypoints=52.4580,5.1090%7C52.4950,5.0700%7C52.5130,5.0480%7C52.6060,4.8890%7C52.4350,5.0000', 'https://commons.wikimedia.org/wiki/Special:FilePath/Paard%20van%20Marken.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Paard%20van%20Marken.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Volendam%20haven.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Kaasmarkt%20Edam.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Museummolen%20Schermerhorn.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Broek%20in%20Waterland.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Monnickendam.jpg"}'::text[], '{"Marken – Paard van Marken","Volendam","Edam – sýrový trh","Museummolen Schermerhorn","Broek in Waterland","Monnickendam"}'::text[], '{"NL"}'::text[], false, 4580, 'approved');

  -- Nizozemsko – Weerribben-Wieden a hanzovní Kampen
  delete from public.routes where name = 'Nizozemsko – Weerribben-Wieden a hanzovní Kampen' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Nizozemsko – Weerribben-Wieden a hanzovní Kampen', 'Okruh největším mokřadem severozápadní Evropy a městy hanzovní slávy: národní park Weerribben-Wieden je bludiště rákosin, kanálů a plovoucích luk, kterým se silnice proplétají po úzkých náspech mezi vodou. Cestou historický přístav Blokzijl se zdymadlem uprostřed náměstí, bývalé hanzovní městečko Vollenhove a monumentální Kampen s branami a věžemi nad řekou IJssel. Start i cíl v Zwolle, jehož gotická brána Sassenpoort patří k nejhezčím v zemi. Rovinatá, ale nesmírně malebná jízda — vodní krajina se mění každým kilometrem. Nejlépe od května do října; v rákosí bývá zrádný boční vítr a silničky jsou úzké, s výhybnami.', 'loop', 120, 190, 'easy',
     '[{"lat": 52.5090, "lng": 6.0950, "label": "Start: Zwolle"}, {"lat": 52.5560, "lng": 5.9110, "label": "Kampen"}, {"lat": 52.6820, "lng": 5.9530, "label": "Vollenhove"}, {"lat": 52.7270, "lng": 5.9600, "label": "Blokzijl"}, {"lat": 52.7810, "lng": 5.9020, "label": "Ossenzijl (Weerribben)"}, {"lat": 52.5090, "lng": 6.0950, "label": "Cíl: Zwolle"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=52.5090,6.0950&destination=52.5090,6.0950&travelmode=driving&waypoints=52.5560,5.9110%7C52.6820,5.9530%7C52.7270,5.9600%7C52.7810,5.9020', 'https://commons.wikimedia.org/wiki/Special:FilePath/Sassenpoort%20Zwolle.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Koornmarktspoort%20Kampen.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Vollenhove.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Blokzijl.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Weerribben.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Sassenpoort%20Zwolle.jpg"}'::text[], '{"Kampen – Koornmarktspoort","Vollenhove","Blokzijl","Nationaal Park Weerribben-Wieden","Zwolle – Sassenpoort"}'::text[], '{"NL"}'::text[], false, 4590, 'approved');

  -- Nizozemsko – Drenthe a okruh TT Assen
  delete from public.routes where name = 'Nizozemsko – Drenthe a okruh TT Assen' and branch_id = v_branch;
