     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Nizozemsko – Drenthe a okruh TT Assen', 'Pouť do „katedrály rychlosti": TT Circuit Assen hostí Velkou cenu motocyklů nepřetržitě od roku 1949 a pro každého motorkáře je to svaté místo. Okolní Drenthe k tomu přidává pravěké megality hunebedden, skanzen Orvelte, památník tábora Westerbork a vřesoviště národního parku Dwingelderveld s obřím radioteleskopem. Jezdí se po klidných alejích mezi lesíky a poli — žádný stres, jen čistá pohoda severního Nizozemska. Trasa je ideální na kombinaci s návštěvou závodů nebo track day na okruhu. Celoročně sjízdná, nejhezčí v srpnu, kdy kvetou vřesoviště; kolem závodního víkendu TT na konci června počítejte s plnými silnicemi i hotely.', 'loop', 130, 200, 'easy',
     '[{"lat": 52.9930, "lng": 6.5620, "label": "Start: Assen"}, {"lat": 52.9620, "lng": 6.5230, "label": "TT Circuit Assen"}, {"lat": 52.9160, "lng": 6.6070, "label": "Kamp Westerbork"}, {"lat": 52.8480, "lng": 6.6730, "label": "Orvelte"}, {"lat": 52.9250, "lng": 6.7920, "label": "Borger"}, {"lat": 52.8120, "lng": 6.4180, "label": "Dwingelderveld"}, {"lat": 52.9930, "lng": 6.5620, "label": "Cíl: Assen"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=52.9930,6.5620&destination=52.9930,6.5620&travelmode=driving&waypoints=52.9620,6.5230%7C52.9160,6.6070%7C52.8480,6.6730%7C52.9250,6.7920%7C52.8120,6.4180', 'https://commons.wikimedia.org/wiki/Special:FilePath/TT%20Circuit%20Assen.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/TT%20Circuit%20Assen.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Kamp%20Westerbork.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Orvelte.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Hunebed%20D27%20Borger.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Dwingelderveld.jpg"}'::text[], '{"TT Circuit Assen","Kamp Westerbork","Orvelte","Hunebedcentrum Borger","Nationaal Park Dwingelderveld"}'::text[], '{"NL"}'::text[], false, 4600, 'approved');

