  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Veere – přístav a Grote Kerk', 'Kdysi bohaté obchodní město, dnes jedno z nejmalebnějších míst Zeelandu. Přístav s historickými plachetnicemi hlídá mohutná Grote Kerk a gotická radnice. Ideální první zastávka na kávu hned po startu.', 51.5470, 3.6670, 'https://commons.wikimedia.org/wiki/Special:FilePath/Grote%20Kerk%20Veere.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Grote%20Kerk%20Veere.jpg"}'::text[], 0),
    (v_route, 'Restaurace: De Campveerse Toren (Veere)', 'Restaurace v obranné věži z 15. století přímo nad vodou — jeden z nejstarších hostinců v Nizozemsku, kde se hodovalo už na svatbě Viléma Oranžského. Výborné mořské plody a výhled na jezero Veerse Meer. Rezervace se v sezóně vyplatí.', 51.5490, 3.6690, 'https://commons.wikimedia.org/wiki/Special:FilePath/Campveerse%20Toren.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Campveerse%20Toren.jpg"}'::text[], 1),
    (v_route, 'Oosterscheldekering', 'Největší z Delta Works — devět kilometrů dlouhá vzdouvací bariéra s 62 ocelovými vraty, po které vede silnice N57. Jízda po ní je zeelandský zážitek číslo jedna: vlevo moře, vpravo delta, nad hlavou racci. Na umělém ostrově Neeltje Jans je návštěvnické centrum Deltaparku.', 51.6218, 3.6870, 'https://commons.wikimedia.org/wiki/Special:FilePath/Oosterscheldekering-pohled.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Oosterscheldekering-pohled.jpg"}'::text[], 2),
    (v_route, 'Zierikzee', 'Hanzovní městečko s více než pěti sty památkami, přístavními branami a nedostavěnou obří věží Sint-Lievensmonstertoren. Historické centrum je kompaktní — motorku nechte u přístavu a projděte se. Cestou zpět přejedete další z hrází Delta Works.', 51.6500, 3.9167, 'https://commons.wikimedia.org/wiki/Special:FilePath/Zierikzee.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Zierikzee.jpg"}'::text[], 3),
    (v_route, 'Westkapelle – maják', 'Nejzápadnější bod ostrova Walcheren s majákem stojícím na mohutné mořské hrázi, kterou za války prorazili Spojenci při osvobozování Zeelandu. Z hráze je výhled na lodní trasu do Antverp. Větrné, syrové a krásné místo.', 51.5280, 3.4430, 'https://commons.wikimedia.org/wiki/Special:FilePath/Vuurtoren%20Westkapelle.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Vuurtoren%20Westkapelle.jpg"}'::text[], 4),
    (v_route, 'Domburg', 'Nejstarší mořské lázně Zeelandu s dlouhou písečnou pláží a promenádou v dunách. Na zmrzlinu nebo rychlé osvěžení před závěrečným úsekem zpět do Middelburgu je to ideální zastávka. V létě tu bývá živo, mimo sezónu klid.', 51.5620, 3.4970, 'https://commons.wikimedia.org/wiki/Special:FilePath/Domburg.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Domburg.jpg"}'::text[], 5);
  insert into public.routes
    (id, branch_id, name, description, route_type, distance_km, duration_min, difficulty,
  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Leeuwarden – Oldehove', 'Hlavní město Fríska a jeho šikmá věž Oldehove — nakloněná víc než ta v Pise a nikdy nedostavěná. Z ochozu je výhled na celé město i okolní polders. Před startem stojí za to projít historické centrum s kanály.', 53.2028, 5.7889, 'https://commons.wikimedia.org/wiki/Special:FilePath/Oldehove%20Leeuwarden.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Oldehove%20Leeuwarden.jpg"}'::text[], 0),
    (v_route, 'Sneek – Waterpoort', 'Vodní brána z roku 1613 s dvojicí věžiček je symbolem fríské vodní turistiky a nejfotografovanější stavbou provincie. Sneek je centrem jachtingu — v přístavu to žije celé léto. Kavárny u vody přímo vybízejí k zastávce.', 53.0330, 5.6580, 'https://commons.wikimedia.org/wiki/Special:FilePath/Waterpoort%20Sneek.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Waterpoort%20Sneek.jpg"}'::text[], 1),
    (v_route, 'Stavoren', 'Nejstarší město Fríska na samém břehu IJsselmeeru, spojené s pověstí o Paní ze Stavorenu. Z mola u majáku je výhled přes celé vnitrozemské moře. Odtud vede trasa po hrázi na sever — nejhezčí úsek okruhu.', 52.8830, 5.3610, 'https://commons.wikimedia.org/wiki/Special:FilePath/Stavoren.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Stavoren.jpg"}'::text[], 2),
    (v_route, 'Hindeloopen', 'Miniaturní přístavní městečko proslulé malovaným nábytkem a vlastním krojem i dialektem. Dřevěné můstky přes kanály, kapitánské domky a muzeum bruslení — Elfstedentocht tu má jednu z nejromantičtějších zastávek. Motorku zaparkujte před centrem, uličky jsou pro pěší.', 52.9420, 5.4030, 'https://commons.wikimedia.org/wiki/Special:FilePath/Hindeloopen.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Hindeloopen.jpg"}'::text[], 3),
    (v_route, 'Workum', 'Protáhlé městečko s dřevěnou zvonicí, historickou váhou a keramickou tradicí. Sídlí tu muzeum naivního malíře Jopieho Huismana, jednoho z nejnavštěvovanějších ve Frísku. Příjemná zastávka na kávu na hlavním náměstí Merk.', 52.9790, 5.4470, 'https://commons.wikimedia.org/wiki/Special:FilePath/Workum.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Workum.jpg"}'::text[], 4),
    (v_route, 'Bolsward – radnice', 'Renesanční radnice z roku 1617 patří k nejkrásnějším v Nizozemsku — bohatě zdobené průčelí s dvojitým schodištěm je chloubou města. Bolsward je také domovem pivovaru Us Heit s frískou whisky. Poslední zastávka před návratem do Leeuwardenu.', 53.0630, 5.5280, 'https://commons.wikimedia.org/wiki/Special:FilePath/Stadhuis%20Bolsward.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Stadhuis%20Bolsward.jpg"}'::text[], 5);
  insert into public.routes
    (id, branch_id, name, description, route_type, distance_km, duration_min, difficulty,
  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Arnhem – John Frostbrug', 'Ten „most příliš vzdálený" z operace Market Garden 1944, pojmenovaný po veliteli britských výsadkářů Johnu Frostovi. Přejedete ho hned na startu — u severního předmostí je památník a expozice. Silný začátek trasy plné historie.', 51.9770, 5.9110, 'https://commons.wikimedia.org/wiki/Special:FilePath/John%20Frostbrug.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/John%20Frostbrug.jpg"}'::text[], 0),
    (v_route, 'Posbank', 'Vyhlídka nad zvlněnými vřesovišti národního parku Veluwezoom a kultovní motorkářský sraz — v neděli dopoledne tu parkují stovky strojů. Silnička přes kopce je nejblíž horské jízdě, co v Nizozemsku najdete. V paviliónu na vrcholu se dá posedět s výhledem.', 52.0330, 6.0210, 'https://commons.wikimedia.org/wiki/Special:FilePath/Posbank.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Posbank.jpg"}'::text[], 1),
    (v_route, 'Bronkhorst', 'Oficiálně nejmenší město Nizozemska — pár dlážděných uliček, hrázděné domky a kaple mezi poli u řeky IJssel. Městská práva má od roku 1482, obyvatel ani dvě stovky. Kouzelná zastávka, kterou projdete za dvacet minut.', 52.0700, 6.1930, 'https://commons.wikimedia.org/wiki/Special:FilePath/Bronkhorst.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Bronkhorst.jpg"}'::text[], 2),
    (v_route, 'Paleis Het Loo', 'Barokní palác oranžské dynastie u Apeldoornu, přezdívaný „Versailles severu". Symetrické zahrady s fontánami a královské interiéry po velké rekonstrukci znovu září. I krátká zastávka u zahrad stojí za to.', 52.2333, 5.9450, 'https://commons.wikimedia.org/wiki/Special:FilePath/Paleis%20Het%20Loo.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Paleis%20Het%20Loo.jpg"}'::text[], 3),
    (v_route, 'Radio Kootwijk', 'Monumentální betonová „katedrála éteru" z roku 1923 uprostřed písečných přesypů Veluwe — odtud se telegrafovalo s Nizozemskou východní Indií. Art deco budova A vypadá jako kulisa sci-fi filmu. Příjezdová silnice dunami je zážitek sama o sobě.', 52.1730, 5.8140, 'https://commons.wikimedia.org/wiki/Special:FilePath/Radio%20Kootwijk.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Radio%20Kootwijk.jpg"}'::text[], 4),
    (v_route, 'Airborne Museum Hartenstein (Oosterbeek)', 'Vila Hartenstein sloužila v září 1944 jako štáb britské 1. výsadkové divize; dnes je z ní strhující muzeum bitvy o Arnhem. Interaktivní expozice Airborne Experience vás vtáhne přímo do bojů. Důstojná tečka před návratem do města.', 51.9880, 5.8320, 'https://commons.wikimedia.org/wiki/Special:FilePath/Airborne%20Museum%20Hartenstein.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Airborne%20Museum%20Hartenstein.jpg"}'::text[], 5);
  insert into public.routes
    (id, branch_id, name, description, route_type, distance_km, duration_min, difficulty,
  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Drielandenpunt (Vaals)', 'Trojmezí Nizozemska, Belgie a Německa na vrcholu Vaalserbergu (322 m) — nejvyšší bod evropského Nizozemska. Stoupání z Vaalsu je nejdelší souvislé „horské" stoupání v zemi a motorkáři si ho užívají po obou stranách hranice. Nahoře rozhledna, labyrint a výhled do tří států.', 50.7540, 6.0210, 'https://commons.wikimedia.org/wiki/Special:FilePath/Drielandenpunt.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Drielandenpunt.jpg"}'::text[], 0),
    (v_route, 'Epen – hrázděný Heuvelland', 'Vesnička v nejjižnějším cípu země, obklopená loukami, potoky a hrázděnými statky — krajina, která připomíná spíš Ardeny než Holandsko. Silničky kolem Epenu patří k nejhezčím v Limburgu. Vyhlídka nad údolím říčky Geul je povinná fotozastávka.', 50.7710, 5.9130, 'https://commons.wikimedia.org/wiki/Special:FilePath/Epen.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Epen.jpg"}'::text[], 1),
    (v_route, 'Restaurace: Gulpener Brouwlokaal (Gulpen)', 'Podniková restaurace nezávislého pivovaru Gulpener přímo na náměstí v Gulpenu — čepují tu celou paletu limburských piv a vaří poctivou regionální kuchyni ze surovin od okolních farmářů. Skvělé místo na oběd v půlce okruhu. Pro řidiče mají i nealko speciály.', 50.8140, 5.8900, 'https://commons.wikimedia.org/wiki/Special:FilePath/Gulpen.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Gulpen.jpg"}'::text[], 2),
    (v_route, 'Kasteel Valkenburg', 'Jediná výšinná hradní zřícenina v Nizozemsku, trůnící na skále nad lázeňským Valkenburgem. Pod hradem se táhnou kilometry chodeb v pískovcových lomech Fluweelengrot. Městečko pod hradem žije turistikou — kavárny na každém rohu.', 50.8620, 5.8320, 'https://commons.wikimedia.org/wiki/Special:FilePath/Kasteel%20Valkenburg.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Kasteel%20Valkenburg.jpg"}'::text[], 3),
    (v_route, 'Cauberg', 'Nejslavnější kopec nizozemské cyklistiky — cíl klasiky Amstel Gold Race a několika mistrovství světa. Krátké prudké stoupání z centra Valkenburgu si vychutnáte i na motorce, jen s respektem k cyklistům, kteří si tu dávají osobáky. Nahoře stojí lázeňský park a kasino.', 50.8590, 5.8210, 'https://commons.wikimedia.org/wiki/Special:FilePath/Cauberg.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Cauberg.jpg"}'::text[], 4),
    (v_route, 'Maastricht – Vrijthof', 'Nejstarší město Nizozemska a jeho nejslavnější náměstí s dvojicí kostelů a řadou kaváren, kde končí každá pořádná limburská vyjížďka. Anděl Páně tu zvoní nad terasami plnými života. Projděte si i středověkou bránu Helpoort a nábřeží Maasy.', 50.8490, 5.6880, 'https://commons.wikimedia.org/wiki/Special:FilePath/Vrijthof%20Maastricht.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Vrijthof%20Maastricht.jpg"}'::text[], 5);
  insert into public.routes
    (id, branch_id, name, description, route_type, distance_km, duration_min, difficulty,
  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Harlingen', 'Jediný fríský námořní přístav — odsud vyplouvají trajekty na ostrovy Vlieland a Terschelling. Nábřeží Noorderhaven lemují kapitánské domy a stěžně historických plachetnic. Nadechněte se moře, než vyrazíte po hrázi na východ.', 53.1740, 5.4210, 'https://commons.wikimedia.org/wiki/Special:FilePath/Harlingen%20haven.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Harlingen%20haven.jpg"}'::text[], 0),
    (v_route, 'Franeker – planetárium Eise Eisingy', 'Nejstarší dosud funkční planetárium světa (1781), které si vlnař Eise Eisinga postavil ve vlastním obýváku — oběžnice se otáčejí na stropě dodnes a od roku 2023 je památkou UNESCO. Geniální stroj poháněný jediným kyvadlem. Krátká odbočka, kterou si nesmíte nechat ujít.', 53.1870, 5.5420, 'https://commons.wikimedia.org/wiki/Special:FilePath/Eise%20Eisinga%20Planetarium.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Eise%20Eisinga%20Planetarium.jpg"}'::text[], 1),
    (v_route, 'Dokkum', 'Nejsevernější z jedenácti fríských měst, kde byl roku 754 zabit svatý Bonifác. Hvězdicové hradby s větrnými mlýny na bastionech obepínají kompaktní historické jádro. Ideální zastávka na kávu v půlce trasy.', 53.3260, 5.9990, 'https://commons.wikimedia.org/wiki/Special:FilePath/Dokkum.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Dokkum.jpg"}'::text[], 2),
    (v_route, 'Nationaal Park Lauwersmeer', 'Bývalý mořský záliv, po přehrazení v roce 1969 proměněný v jezerní divočinu — dnes ptačí ráj a park tmavé oblohy. Silnice po hrázi kolem přístavu Lauwersoog odděluje sladkou a slanou vodu. Na obzoru se rýsuje ostrov Schiermonnikoog.', 53.4000, 6.2200, 'https://commons.wikimedia.org/wiki/Special:FilePath/Lauwersmeer.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Lauwersmeer.jpg"}'::text[], 3),
    (v_route, 'Zoutkamp', 'Bývalá rybářská vesnice s flotilou krevetových kutrů a pestrobarevnými domky u přístavu. Místní uzené krevety jsou pojem — kupte si kornout přímo od rybáře. Groningenský venkov v nejryzejší podobě.', 53.3370, 6.2940, 'https://commons.wikimedia.org/wiki/Special:FilePath/Zoutkamp.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Zoutkamp.jpg"}'::text[], 4),
    (v_route, 'Pieterburen', 'Vesnička proslulá záchrannou stanicí pro tuleně ze sousedního Waddenského moře — uzdravené kusy se tu vypouštějí zpátky. Začíná zde i slavná pouť bahnem wadlopen, chůze po mořském dně při odlivu. Důstojný cíl trasy na konci světa.', 53.3960, 6.4400, 'https://commons.wikimedia.org/wiki/Special:FilePath/Pieterburen.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Pieterburen.jpg"}'::text[], 5);
  insert into public.routes
    (id, branch_id, name, description, route_type, distance_km, duration_min, difficulty,
  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Restaurace: De Twaalf Balcken (Den Burg)', 'Historická hospoda s dvanácti trámy v centru Den Burgu, kde se schází ostrovani i výletníci. Na talíři texelské jehněčí a ryby z Waddenského moře, k tomu místní pivo z ostrovního pivovaru. Poctivý ostrovní oběd hned po trajektu.', 53.0540, 4.7970, 'https://commons.wikimedia.org/wiki/Special:FilePath/Den%20Burg.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Den%20Burg.jpg"}'::text[], 0),
    (v_route, 'Oudeschild – muzeum Kaap Skil', 'Rybářský přístav s muzeem námořních nálezů — texelská rejda bývala kotvištěm lodí Východoindické společnosti a mořské dno kolem je archiv vraků. Maketa vesnice, mlýn a kutry přímo za oknem. U přístavu se suší sítě a smaží ryby.', 53.0390, 4.8500, 'https://commons.wikimedia.org/wiki/Special:FilePath/Oudeschild.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Oudeschild.jpg"}'::text[], 1),
    (v_route, 'Ecomare', 'Záchranná stanice tuleňů a centrum přírody Waddenského moře na kraji dun u De Koog. Krmení tuleňů je zážitek pro každého, expozice vysvětlí, proč je wadden UNESCO. Odtud vede pěšina rovnou do dun národního parku.', 53.0930, 4.7560, 'https://commons.wikimedia.org/wiki/Special:FilePath/Ecomare.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Ecomare.jpg"}'::text[], 2),
    (v_route, 'Nationaal Park Duinen van Texel', 'Pás dun, vřesovišť a slaných luk podél celého západního pobřeží ostrova. Silnička mezi De Koog a severním cípem patří k nejhezčím úsekům trasy — duny po levici, pastviny po pravici. Na jaře tu hnízdí kolonie racků a rybáků.', 53.1000, 4.7660, 'https://commons.wikimedia.org/wiki/Special:FilePath/Duinen%20van%20Texel.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Duinen%20van%20Texel.jpg"}'::text[], 3),
    (v_route, 'Maják Eierland', 'Červený maják z roku 1864 na písečné výspě úplně na severu Texelu — symbol ostrova a cíl trasy. Z ochozu dohlédnete na sousední Vlieland, dole duní příboj Severního moře. Ideální místo na západ slunce před zpátečním trajektem.', 53.1790, 4.8550, 'https://commons.wikimedia.org/wiki/Special:FilePath/Vuurtoren%20Eierland.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Vuurtoren%20Eierland.jpg"}'::text[], 4);
  insert into public.routes
    (id, branch_id, name, description, route_type, distance_km, duration_min, difficulty,
  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Circuit Zandvoort', 'Legendární okruh v dunách u Severního moře, od roku 2021 opět dějiště Velké ceny Nizozemska F1 s klopenou zatáčkou Arie Luyendyk. V kalendáři bývají i motorkářské track days a veřejné jízdy. I bez vjezdu na trať stojí za zastávku — tribuny se zvedají přímo z dun.', 52.3888, 4.5409, 'https://commons.wikimedia.org/wiki/Special:FilePath/Circuit%20Zandvoort.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Circuit%20Zandvoort.jpg"}'::text[], 0),
    (v_route, 'Noordwijk – maják', 'Elegantní přímořské letovisko s bílým majákem a širokou promenádou nad pláží. Silnice sem vede dunovou rezervací — nejhezčí přímořský úsek okruhu. Na boulevardu si dejte čerstvého sledě nebo kibbeling.', 52.2420, 4.4320, 'https://commons.wikimedia.org/wiki/Special:FilePath/Vuurtoren%20Noordwijk.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Vuurtoren%20Noordwijk.jpg"}'::text[], 1),
    (v_route, 'Keukenhof', 'Nejslavnější květinový park světa: sedm milionů cibulovin na 32 hektarech, otevřeno jen od poloviny března do poloviny května. Přehlídka toho nejlepšího, co nizozemské šlechtitelství dokáže. Parkování u vstupu, ve špičce přijeďte před desátou.', 52.2700, 4.5460, 'https://commons.wikimedia.org/wiki/Special:FilePath/Keukenhof.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Keukenhof.jpg"}'::text[], 2),
    (v_route, 'Tulipánová pole u Lisse', 'Lány tulipánů, hyacintů a narcisů kolem Lisse jsou v dubnu barevnější než cokoliv, co jste kdy viděli — pruhy červené, žluté a fialové až k obzoru. Polními silničkami se dá mezi lány projíždět, jen nevstupujte do polí. Vůně hyacintů je cítit i přes helmu.', 52.2580, 4.5570, 'https://commons.wikimedia.org/wiki/Special:FilePath/Bollenvelden%20bij%20Lisse.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Bollenvelden%20bij%20Lisse.jpg"}'::text[], 3),
    (v_route, 'Haarlem – Grote Markt', 'Jedno z nejkrásnějších náměstí Nizozemska pod věží katedrály Sint-Bavo, obklopené renesančními štíty a terasami. Haarlem je menší a klidnější sestra Amsterdamu — atmosféra stejná, davy poloviční. Skvělé místo na závěrečnou kávu.', 52.3810, 4.6360, 'https://commons.wikimedia.org/wiki/Special:FilePath/Grote%20Markt%20Haarlem.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Grote%20Markt%20Haarlem.jpg"}'::text[], 4),
    (v_route, 'Restaurace: Jopenkerk (Haarlem)', 'Pivovar a restaurace v odsvěceném kostele z roku 1910 — haarlemská značka Jopen tu vaří piva podle receptur z 15. století a kuchyně k nim ladí menu. Industriálně-gotický interiér s měděnými tanky pod vitrážemi je zážitek sám o sobě. Po vyjížďce ideální tečka, pro jezdce nealko Jopen.', 52.3820, 4.6320, 'https://commons.wikimedia.org/wiki/Special:FilePath/Jopenkerk%20Haarlem.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Jopenkerk%20Haarlem.jpg"}'::text[], 5);
