  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Marken – Paard van Marken', 'Bývalý ostrov s dřevěnými domky na kůlech, dnes spojený s pevninou hrází, po které se na motorce krásně jede. Na východním cípu stojí maják Paard van Marken — „markenský kůň" z roku 1839, k němuž vede krátká procházka po hrázi. Vesnice si drží starosvětský ráz včetně krojů při slavnostech.', 52.4580, 5.1090, 'https://commons.wikimedia.org/wiki/Special:FilePath/Paard%20van%20Marken.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Paard%20van%20Marken.jpg"}'::text[], 0),
    (v_route, 'Volendam', 'Nejslavnější rybářská vesnice Nizozemska s přístavní promenádou plnou stánků s uzeným úhořem a sleděm. Turistický ruch k Volendamu patří, ale atmosféra starého přístavu funguje pořád. Ochutnejte paling — uzeného úhoře — přímo u vody.', 52.4950, 5.0700, 'https://commons.wikimedia.org/wiki/Special:FilePath/Volendam%20haven.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Volendam%20haven.jpg"}'::text[], 1),
    (v_route, 'Edam – sýrový trh', 'Městečko, které dalo jméno nejexportovanějšímu sýru světa. V létě se na náměstí u váhy koná tradiční sýrový trh s nosiči a dřevěnými čluny plnými bochníků. Mimo trh je Edam tichý labyrint kanálů, mostků a sýráren s ochutnávkami.', 52.5130, 5.0480, 'https://commons.wikimedia.org/wiki/Special:FilePath/Kaasmarkt%20Edam.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Kaasmarkt%20Edam.jpg"}'::text[], 2),
    (v_route, 'Museummolen Schermerhorn', 'Trojice poldrových mlýnů z roku 1635 v řadě u kanálu — jeden slouží jako muzeum, kde uvidíte, jak mlýny přečerpávaly vodu a odvodnily celou Schermer. Mlynářská rodina tu žila mezi převody a lopatkami. Autentičtější mlýnský zážitek než na přeplněných slavných místech.', 52.6060, 4.8890, 'https://commons.wikimedia.org/wiki/Special:FilePath/Museummolen%20Schermerhorn.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Museummolen%20Schermerhorn.jpg"}'::text[], 3),
    (v_route, 'Broek in Waterland', 'Vesnice dřevěných domů natřených typickou šedozelenou „broekskou" barvou, se zamrzajícím jezírkem uprostřed. V 17. století tu bohatí amsterdamští kupci stavěli letní sídla. Pět minut zastávky, sto let zpátky v čase.', 52.4350, 5.0000, 'https://commons.wikimedia.org/wiki/Special:FilePath/Broek%20in%20Waterland.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Broek%20in%20Waterland.jpg"}'::text[], 4),
    (v_route, 'Monnickendam', 'Přístavní městečko se zvonkohrou ve věži Speeltoren a udírnami ryb u kotviště plachetnic. Menší a klidnější než Volendam, o to autentičtější. Start i cíl okruhu — večer tu u přístavu příjemně posedíte.', 52.4570, 5.0380, 'https://commons.wikimedia.org/wiki/Special:FilePath/Monnickendam.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Monnickendam.jpg"}'::text[], 5);
