  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Kampen – Koornmarktspoort', 'Hanzovní veterán na břehu IJsselu: panorama věží, tří městských bran a nábřeží patřilo ve středověku k nejbohatším pohledům Evropy. Koornmarktspoort u řeky je nejstarší z bran. Přejezd mostu přes IJssel s výhledem na město je zážitek.', 52.5560, 5.9110, 'https://commons.wikimedia.org/wiki/Special:FilePath/Koornmarktspoort%20Kampen.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Koornmarktspoort%20Kampen.jpg"}'::text[], 0),
    (v_route, 'Vollenhove', 'Bývalé „město paláců", kde šlechta stavěla sídla u dnes zaniklého moře Zuiderzee. Přístav, zámecké zahrady a kostely připomínají zašlou slávu. Odtud začíná nejhezčí úsek podél okraje mokřadů.', 52.6820, 5.9530, 'https://commons.wikimedia.org/wiki/Special:FilePath/Vollenhove.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Vollenhove.jpg"}'::text[], 1),
    (v_route, 'Blokzijl', 'Miniaturní přístavní město se zdymadlem přímo uprostřed náměstí a domy zlatého věku kolem kotviště. Kdysi rušný přístav Zuiderzee, dnes brána do vodního světa Weerribben. Kavárny u přístavu jsou stvořené pro pauzu.', 52.7270, 5.9600, 'https://commons.wikimedia.org/wiki/Special:FilePath/Blokzijl.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Blokzijl.jpg"}'::text[], 2),
    (v_route, 'Nationaal Park Weerribben-Wieden', 'Největší souvislý rašelinný mokřad severozápadní Evropy, vzniklý staletími těžby rašeliny — dnes ráj vyder, orlovců a černých rybáků. Silnička z Blokzijlu přes Ossenzijl vede přímo skrz rákosové moře. U návštěvnického centra se dá půjčit šlapací člun na rychlou vodní odbočku.', 52.7810, 5.9020, 'https://commons.wikimedia.org/wiki/Special:FilePath/Weerribben.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Weerribben.jpg"}'::text[], 3),
    (v_route, 'Zwolle – Sassenpoort', 'Gotická městská brána z roku 1409 se čtyřmi věžičkami je symbolem hanzovního Zwolle. Historické jádro v hradebním prstenci má hvězdicový půdorys a skvělé podniky na závěrečné jídlo. Důstojné zakončení hanzovního okruhu.', 52.5090, 6.0950, 'https://commons.wikimedia.org/wiki/Special:FilePath/Sassenpoort%20Zwolle.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Sassenpoort%20Zwolle.jpg"}'::text[], 4);
