  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'TT Circuit Assen', 'Jediný okruh, který hostí motocyklovou Grand Prix bez přerušení od založení šampionátu — Dutch TT je pro motorkáře totéž co Wimbledon pro tenisty. Mimo závodní víkendy fungují track days, vyhlídkové jízdy i prohlídky zázemí. U brány stojí pomník vítězů a fanouškovský obchod.', 52.9620, 6.5230, 'https://commons.wikimedia.org/wiki/Special:FilePath/TT%20Circuit%20Assen.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/TT%20Circuit%20Assen.jpg"}'::text[], 0),
    (v_route, 'Kamp Westerbork', 'Památník tranzitního tábora, odkud za okupace odjížděly transporty do vyhlazovacích táborů — mezi deportovanými byla i Anne Franková. Zvednuté koleje památníku patří k nejpůsobivějším pietním místům Evropy. Zastávka, která dá celé vyjížďce hloubku.', 52.9160, 6.6070, 'https://commons.wikimedia.org/wiki/Special:FilePath/Kamp%20Westerbork.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Kamp%20Westerbork.jpg"}'::text[], 1),
    (v_route, 'Orvelte', 'Živý skanzen — památkově chráněná vesnice, kde se dodnes normálně žije, ale auta musí zůstat venku. Doškové statky, kovárna, sýrárna a řemeslné dílny podél dlážděné návsi. Motorku zaparkujete na kraji a projdete se stoletím zpět.', 52.8480, 6.6730, 'https://commons.wikimedia.org/wiki/Special:FilePath/Orvelte.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Orvelte.jpg"}'::text[], 2),
    (v_route, 'Hunebedcentrum Borger', 'Největší nizozemský dolmen — hunebed D27 z doby před 5000 lety — leží hned u muzea megalitické kultury. Obří balvany sem dotlačil ledovec ze Skandinávie, hroby z nich poskládali první zemědělci Evropy. Podél trasy potkáte hunebedů víc, Drenthe jich má přes padesát.', 52.9250, 6.7920, 'https://commons.wikimedia.org/wiki/Special:FilePath/Hunebed%20D27%20Borger.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Hunebed%20D27%20Borger.jpg"}'::text[], 3),
    (v_route, 'Nationaal Park Dwingelderveld', 'Největší vlhké vřesoviště západní Evropy s bludnými balvany, jalovci a stády ovcí — v srpnu celé fialové. Nad krajinou se otáčí historický radioteleskop, který kdysi jako první zmapoval spirální ramena Galaxie. Tichá silnička po okraji parku je krásné zakončení okruhu.', 52.8120, 6.4180, 'https://commons.wikimedia.org/wiki/Special:FilePath/Dwingelderveld.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Dwingelderveld.jpg"}'::text[], 4);
